from pathlib import Path
import json,numpy as np,pandas as pd
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'campaigns'/'CAM-0626'/'artifacts'/'RUN-0011';KEY=['symbol','target_ts','role']
l=pd.read_parquet(OUT/'ledger.parquet');l.date=pd.to_datetime(l.date);l.target_ts=pd.to_datetime(l.target_ts,utc=True);q=pd.concat([pd.read_parquet(p) for p in OUT.glob('quotes*.parquet')],ignore_index=True);q.target_ts=pd.to_datetime(q.target_ts,utc=True);q.quote_ts=pd.to_datetime(q.quote_ts,utc=True);q['delay']=(q.quote_ts-q.target_ts).dt.total_seconds();q=q[(q.delay>=0)&(q.delay<=60)].sort_values(['delay','quote_ts']).drop_duplicates(KEY);z=l.merge(q,on=KEY,how='left',validate='one_to_one');z['exit_fill']=z.ask_price;z['gross_pnl']=1-z.exit_fill/z.entry_fill;days=pd.DataFrame({'date':pd.to_datetime(pd.read_parquet(ROOT/'campaigns'/'CAM-0626'/'artifacts'/'RUN-0010'/'passive_fills.parquet').date.unique())});rows=[]
